shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #dcd6c8;
    --line-strong: #1e1d1b;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #28415a;
    --crimson: #9e2a2b;
    --forest: #2d5a4c;
    --gold: #c99738;

    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Lora', Georgia, serif;
    --font-serif-en: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    font-family: var(--font-serif-cn);
    color: var(--body);
    line-height: 1.8;
    overflow-x: hidden;
    width: 100%;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
  }

  /* Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Reading Progress Bar */
  .progress-rail {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: rgba(20, 20, 19, 0.08);
    z-index: 1001;
  }
  .progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0 24px;
    height: 56px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .masthead-left {
    display: flex;
    align-items: center;
    gap: 14px;
  }

  .wsj-brand {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .masthead-divider {
    width: 1px;
    height: 16px;
    background: var(--line);
  }

  .series-tag {
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .masthead-center {
    display: flex;
    align-items: center;
    gap: 20px;
  }

  .chapter-pill {
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 500;
    color: var(--muted);
    text-decoration: none;
    transition: color 0.2s;
  }
  .chapter-pill:hover {
    color: var(--ink);
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 3px;
    gap: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.74rem;
    font-weight: 600;
    padding: 4px 12px;
    border-radius: 999px;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Layout Containers */
  .container-wide {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 32px;
  }

  .container-editorial {
    max-width: 1120px;
    margin: 0 auto;
    padding: 0 32px;
  }

  /* Hero Header */
  .hero-header {
    padding: 64px 0 48px;
    border-bottom: 1px solid var(--line);
  }

  .hero-kicker-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
  }

  .hero-kicker-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--accent);
  }

  .hero-title {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: clamp(2.25rem, 4.4vw, 3.85rem);
    line-height: 1.14;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 20px;
    max-width: 960px;
  }

  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.22;
    letter-spacing: -0.01em;
  }

  .hero-dek {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.15rem, 2vw, 1.48rem);
    line-height: 1.55;
    color: var(--muted);
    font-weight: 400;
    max-width: 820px;
    margin-bottom: 32px;
  }

  :host([lang="en"]) .hero-dek {
    font-family: var(--font-serif-en);
    font-style: italic;
  }

  .hero-meta-grid {
    display: grid;
    grid-template-columns: 1fr 1.35fr;
    gap: 32px;
    padding-top: 28px;
    border-top: 2px solid var(--ink);
    align-items: start;
  }

  .byline-block {
    font-family: var(--font-sans);
  }

  .byline-author {
    font-size: 0.92rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 4px;
  }

  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
    margin-bottom: 16px;
  }

  .key-ledger-strip {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    padding-top: 12px;
    border-top: 1px solid var(--line);
  }

  .mini-stat-val {
    font-family: var(--font-mono);
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--ink);
  }
  .mini-stat-lbl {
    font-family: var(--font-sans);
    font-size: 0.72rem;
    color: var(--muted);
    line-height: 1.35;
  }

  /* Context Dossier Box (ctx1) */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-left: 4px solid var(--accent);
    padding: 20px 24px;
    border-radius: 2px;
  }

  .dossier-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
    font-family: var(--font-sans);
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
  }

  .dossier-body {
    font-size: 0.94rem;
    line-height: 1.72;
    color: var(--body);
  }

  /* Editorial Grid Architecture */
  .editorial-section {
    padding: 56px 0;
    border-bottom: 1px solid var(--line);
  }

  .section-banner {
    display: flex;
    align-items: baseline;
    gap: 16px;
    margin-bottom: 36px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--line);
  }

  .section-num {
    font-family: var(--font-mono);
    font-size: 0.82rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .section-heading {
    font-family: var(--font-display);
    font-size: clamp(1.45rem, 2.4vw, 2rem);
    font-weight: 700;
    color: var(--ink);
    line-height: 1.25;
  }

  .grid-asymmetric {
    display: grid;
    grid-template-columns: minmax(0, 650px) minmax(280px, 380px);
    justify-content: space-between;
    gap: 48px;
    align-items: start;
  }

  .prose-column {
    min-width: 0;
  }

  .rail-column {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 28px;
    position: sticky;
    top: 80px;
  }

  /* Prose Styling & Chinese Typography Discipline */
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.88;
    color: var(--body);
    margin-bottom: 1.55em;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    line-height: 1.82;
  }

  /* Lead paragraph stature instead of CSS first-letter drop-cap */
  .lead-paragraph {
    font-size: 1.28rem !important;
    line-height: 1.78 !important;
    color: var(--ink);
    font-weight: 600;
    padding-left: 18px;
    border-left: 3px solid var(--accent);
    margin-bottom: 1.75em;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: var(--accent-soft);
    color: inherit;
    padding: 0.06em 0.28em;
    border-bottom: 1.5px solid rgba(184, 93, 25, 0.55);
    border-radius: 2px;
    font-weight: 600;
  }

  /* Derived Metric Cards */
  .metric-card {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-top: 3px solid var(--ink);
    padding: 20px 22px;
    border-radius: 2px;
  }

  .metric-card.accent-top {
    border-top-color: var(--accent);
  }

  .metric-val {
    font-family: var(--font-mono);
    font-size: 2rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.15;
    margin-bottom: 8px;
    letter-spacing: -0.02em;
  }

  .metric-card.accent-top .metric-val {
    color: var(--accent);
  }

  .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 6px;
    line-height: 1.4;
  }

  .metric-note {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: var(--muted);
    line-height: 1.5;
  }

  /* Derived Pull Quotes */
  .pull-quote {
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
    padding: 22px 24px;
    margin: 8px 0;
  }

  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.08rem;
    line-height: 1.62;
    color: var(--ink);
    margin-bottom: 12px;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--muted);
    line-height: 1.4;
  }

  /* Inline Narrative Quote Treatment (p4 split) */
  .inline-adviser-callout {
    margin: 28px 0 32px;
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-left: 4px solid var(--accent);
    padding: 22px 26px;
  }

  .inline-adviser-attribution {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    color: var(--muted);
    margin-bottom: 10px;
  }

  .inline-adviser-quote {
    font-family: var(--font-display);
    font-size: 1.22rem;
    line-height: 1.55;
    color: var(--ink);
    font-weight: 700;
  }

  /* Visual Exhibit Frame */
  .exhibit-box {
    background: #ffffff;
    border: 1px solid var(--line);
    padding: 28px;
    margin: 36px 0;
    box-shadow: 0 4px 20px rgba(20, 20, 19, 0.03);
  }

  .exhibit-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 6px;
  }

  .exhibit-title {
    font-family: var(--font-sans);
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 6px;
    line-height: 1.35;
  }

  .exhibit-sub {
    font-family: var(--font-sans);
    font-size: 0.84rem;
    color: var(--muted);
    margin-bottom: 22px;
    line-height: 1.5;
  }

  .exhibit-svg-wrap {
    width: 100%;
    overflow: hidden;
  }

  .exhibit-svg-wrap svg {
    width: 100%;
    height: auto;
    display: block;
  }

  .exhibit-footnote {
    margin-top: 16px;
    padding-top: 12px;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.75rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Corporate Defense Counterpoint Box (p13, p14) */
  .defense-dossier {
    background: var(--navy-bg);
    color: #f2efe9;
    padding: 32px;
    margin: 36px 0;
    border-radius: 3px;
    border-top: 4px solid var(--gold);
  }

  .defense-kicker {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--gold);
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .defense-dossier .prose-p {
    color: #eae6df;
    font-size: 1.05rem;
    margin-bottom: 1.2em;
  }

  .defense-dossier .prose-p:last-child {
    margin-bottom: 0;
  }

  .defense-dossier mark.ed-hl {
    background: rgba(201, 151, 56, 0.25);
    border-bottom-color: var(--gold);
    color: #ffffff;
  }

  /* Metric Trio Strip */
  .metric-trio-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin: 32px 0;
  }

  /* Climactic Verdict Box (p20.s2) */
  .verdict-box {
    background: var(--ink);
    color: var(--paper);
    padding: 36px 36px;
    margin-top: 28px;
    border-left: 5px solid var(--accent);
    position: relative;
  }

  .verdict-kicker {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    margin-bottom: 14px;
  }

  .verdict-quote {
    font-family: var(--font-display);
    font-size: clamp(1.35rem, 2.2vw, 1.78rem);
    line-height: 1.45;
    color: #ffffff;
    font-weight: 700;
  }

  .verdict-quote mark.ed-hl {
    background: rgba(184, 93, 25, 0.35);
    border-bottom-color: var(--accent);
    color: #ffffff;
  }

  /* Footer */
  .editorial-footer {
    padding: 48px 0 64px;
    background: var(--paper-card);
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
  }

  .footer-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
  }

  /* Responsive Design (1440px down to 390px) */
  @media (max-width: 980px) {
    .hero-meta-grid {
      grid-template-columns: 1fr;
      gap: 24px;
    }
    .grid-asymmetric {
      grid-template-columns: 1fr;
      gap: 32px;
    }
    .rail-column {
      position: static;
    }
    .masthead-center {
      display: none;
    }
  }

  @media (max-width: 640px) {
    .masthead {
      padding: 0 14px;
      height: 52px;
    }
    .series-tag, .masthead-divider {
      display: none;
    }
    .container-wide, .container-editorial {
      padding: 0 18px;
    }
    .hero-header {
      padding: 36px 0 32px;
    }
    .hero-title {
      font-size: 1.95rem;
    }
    .hero-dek {
      font-size: 1.08rem;
    }
    .key-ledger-strip {
      grid-template-columns: 1fr;
      gap: 10px;
    }
    .editorial-section {
      padding: 36px 0;
    }
    .prose-p {
      font-size: 1.05rem;
      line-height: 1.8;
    }
    .lead-paragraph {
      font-size: 1.14rem !important;
      padding-left: 14px;
    }
    .exhibit-box {
      padding: 18px 14px;
      margin: 24px 0;
    }
    .metric-trio-grid {
      grid-template-columns: 1fr;
    }
    .defense-dossier {
      padding: 22px 18px;
    }
    .verdict-box {
      padding: 24px 20px;
    }
  }
